import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const source = resolve(
  "server/db/ddl/planes/neon/master/12_certification_reference_seed.sql",
);
const target = resolve(
  "server/db/ddl/planes/mesh/mesh/12_certification_reference_seed.sql",
);

const neonCatalog = await readFile(source, "utf8");
const meshCatalog = neonCatalog
  .replace(
    "-- Platform-wide certification types",
    "-- Generated from the Neon certification reference catalog. Do not edit this file directly.\n-- Platform-wide certification types",
  )
  .replaceAll("master.certification_type", "mesh.certification_type");

await writeFile(target, meshCatalog);
console.log("Synchronized the Neon/Mesh certification reference catalog.");
